//go:build ignore

// Copy into upstream converter/xlsx and run TestCodexXLSXCells.
package xlsx
import("archive/zip";"bytes";"encoding/json";"fmt";"math/rand";"os";"path/filepath";"testing")
func TestCodexXLSXCells(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};samples:=[][]byte{};for _,name:=range []string{"basic.xlsx","features.xlsx","form-fixed.xlsx","form-pages.xlsx","form-rows.xlsx","math.xlsx","print.xlsx"}{b,e:=os.ReadFile(filepath.Join("testdata",name));if e!=nil{t.Fatal(e)};samples=append(samples,b)};r:=rand.New(rand.NewSource(736272));cells:=[]string{`<c r="A1"><v>3.5</v></c>`,`<c r="B1" t="s"><v>0</v></c>`,`<c r="C1" t="s"><v>1</v></c>`,`<c t="inlineStr"><is><r><t>Hello </t></r><r><t>World</t></r></is></c>`,`<c t="inlineStr"><v>literal</v></c>`,`<c t="str"><v>Hello_x000A_World</v></c>`,`<c t="b"><v>True</v></c>`,`<c t="e"><v> #DIV/0! </v></c>`,`<c t="d"><v>2024-02-29T12:34:56Z</v></c>`,`<c s="3"><f>SUM(A1:A4)</f><v>42</v></c>`,`<c s="4"><f>A1+1</f></c>`,`<c><v/></c>`,`<c t="s"><v>999</v></c>`,`<c r="Z10" t="inlineStr"><is><t> x &amp; y </t></is></c>`,`<c r="not-a-ref" t="n"><v>-12e4</v></c>`,`<c t="b"><v>1</v></c>`,`<c t="str"><f>1+1</f><v/></c>`};for i:=0;i<1300;i++{var b bytes.Buffer;z:=zip.NewWriter(&b);add:=func(name,content string){f,e:=z.Create(name);if e!=nil{t.Fatal(e)};f.Write([]byte(content))};add("xl/workbook.xml",`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="S" r:id="rId1"/></sheets></workbook>`);add("xl/_rels/workbook.xml.rels",`<Relationships><Relationship Id="rId1" Type="x/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="x/sharedStrings" Target="sharedStrings.xml"/></Relationships>`);add("xl/sharedStrings.xml",`<sst><si><t>one</t></si><si><r><t>two</t></r><r><t> three</t></r></si></sst>`);s:=`<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>`;for j:=0;j<1+r.Intn(10);j++ {s+=fmt.Sprintf(`<row r="%d" ht="%.1f" hidden="%d" customHeight="%d" s="%d" customFormat="%d">`,r.Intn(15)+1,float64(r.Intn(1000))/2,r.Intn(2),r.Intn(2),r.Intn(7),r.Intn(2));for k:=0;k<r.Intn(15);k++{s+=cells[r.Intn(len(cells))]};s+="</row>"};s+="</sheetData></worksheet>";add("xl/worksheets/sheet1.xml",s);if e:=z.Close();e!=nil{t.Fatal(e)};samples=append(samples,append([]byte{},b.Bytes()...))};out:=[]any{};for _,data:=range samples{c,_,e:=openWorkbook(bytes.NewReader(data),int64(len(data)),&Options{NoSystemFonts:true,SystemFonts:true});if e!=nil{t.Fatal(e)};for _,sheet:=range c.sheets{if sheet.chart{continue};ws,e:=c.readWorksheet(sheet.part);if e!=nil{t.Fatal(e)};rows:=[]any{};for _,row:=range ws.rows{cells:=[]any{};for _,cell:=range row.cells{text:="";if cell.text!=nil{text=cell.text.plain};cells=append(cells,[]any{cell.col,cell.style,int(cell.kind),cell.num,text})};rows=append(rows,[]any{row.idx,row.ht,row.custom,row.hidden,row.style,cells})};ws.sortRows();sorted:=[]any{};for _,row:=range ws.rows{cells:=[]any{};for _,cell:=range row.cells{text:="";if cell.text!=nil{text=cell.text.plain};cells=append(cells,[]any{cell.col,cell.style,int(cell.kind),cell.num,text})};sorted=append(sorted,[]any{row.idx,row.ht,row.custom,row.hidden,row.style,cells})};out=append(out,map[string]any{"input":data,"part":sheet.part,"want":[]any{rows,ws.noValue,sorted}})}};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/xlsx/cells.json"),b,0644);e!=nil{t.Fatal(e)}}
